    /**
     * @param FlatBufferBuilder $builder
     * @return int table offset
     */
    public static function endAIS(FlatBufferBuilder $builder)
    {
        $o = $builder->endObject();
        $builder->required($o, 4);  // EVENT_ID
        $builder->required($o, 6);  // SESSION_ID
        return $o;
    }

    public static function finishAISBuffer(FlatBufferBuilder $builder, $offset)
    {
        $builder->finish($offset, '$AIS');
    }
